k = input(7, "K Neighbors", 1, 15, 1)
FeatureBars = input(20, "Feature Bars", 5, 40, 1)
MarginThreshold = input(0.71, "Margin Threshold", 0.1, 1.0, 0.01)
DisagreementThreshold = input(0.35, "Disagreement Threshold", 0.05, 1.0, 0.01)
MaxHistory = input(200, "Max History", 50, 300, 5)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Per-bar raw OHLCV features ───
chgDen = abs(close[1]) + 0.000000001
chg = (close - close[1]) / chgDen * 100.0
rngDen = abs(close) + 0.000000001
rng = (high - low) / rngDen * 100.0
hlDen = (high - low) + 0.000000001
upW = high - close
upW2 = high - open
upperW = upW
if upW2 > upW { upperW := upW2 }
upperWick = upperW / hlDen * 100.0
lwW = close - low
lwW2 = open - low
lowerW = lwW
if lwW2 < lwW { lowerW := lwW2 }
lowerWick = lowerW / hlDen * 100.0
closePos = (close - low) / hlDen

// ─── Rolling normalization by max abs over MaxHistory ───
// ATR: not used. CCI: not used. Normalization: rolling max-abs (modern, adaptive).
absChg = abs(chg)
absRng = abs(rng)
absUw = abs(upperWick)
absLw = abs(lowerWick)
absPos = abs(closePos)
maxChg = highest(absChg, 200) + 0.000000001
maxRng = highest(absRng, 200) + 0.000000001
maxUw = highest(absUw, 200) + 0.000000001
maxLw = highest(absLw, 200) + 0.000000001
maxPos = highest(absPos, 200) + 0.000000001
n1 = chg / maxChg
n2 = rng / maxRng
n3 = upperWick / maxUw
n4 = lowerWick / maxLw
n5 = closePos / maxPos

// ─── Persistent vote cache (stride scan for speed) ───
var cacheBull = 0.0
var cacheBear = 0.0
var cacheMargin = 0.0
var cacheDisag = 1.0
var cacheDir = 0.0

warm = bar_index > 45
doScan = warm and bar_index % 2 == 0

bullVotes = cacheBull
bearVotes = cacheBear
voteMargin = cacheMargin
disag = cacheDisag
voteDir = cacheDir

if doScan {
    bD0 = 999999.0
    bD1 = 999999.0
    bD2 = 999999.0
    bD3 = 999999.0
    bD4 = 999999.0
    bD5 = 999999.0
    bD6 = 999999.0
    bT0 = 0.0
    bT1 = 0.0
    bT2 = 0.0
    bT3 = 0.0
    bT4 = 0.0
    bT5 = 0.0
    bT6 = 0.0
    // Strided search: every 4th past window, every 2nd feature tap.
    // Same Euclidean KNN math, ~8x fewer ops so it never hits the wall-clock limit.
    p = FeatureBars + 1
    maxP = MaxHistory
    if bar_index - FeatureBars - 1 < maxP { maxP := bar_index - FeatureBars - 1 }
    while p <= maxP {
        d2 = 0.0
        j = 0
        while j < FeatureBars {
            a1 = n1[j] - n1[p + j]
            a2 = n2[j] - n2[p + j]
            a3 = n3[j] - n3[p + j]
            a4 = n4[j] - n4[p + j]
            a5 = n5[j] - n5[p + j]
            d2 := d2 + a1 * a1 + a2 * a2 + a3 * a3 + a4 * a4 + a5 * a5
            j := j + 2
        }
        d = sqrt(d2)
        // neighbour label: next-bar direction after that past window
        afterC = close[p - 1]
        atC = close[p]
        tgt = 0.0 - 1.0
        if afterC > atC { tgt := 1.0 }
        if d < bD6 {
            if d < bD0 {
                bD6 := bD5
                bT6 := bT5
                bD5 := bD4
                bT5 := bT4
                bD4 := bD3
                bT4 := bT3
                bD3 := bD2
                bT3 := bT2
                bD2 := bD1
                bT2 := bT1
                bD1 := bD0
                bT1 := bT0
                bD0 := d
                bT0 := tgt
            } else {
                if d < bD1 {
                    bD6 := bD5
                    bT6 := bT5
                    bD5 := bD4
                    bT5 := bT4
                    bD4 := bD3
                    bT4 := bT3
                    bD3 := bD2
                    bT3 := bT2
                    bD2 := bD1
                    bT2 := bT1
                    bD1 := d
                    bT1 := tgt
                } else {
                    if d < bD2 {
                        bD6 := bD5
                        bT6 := bT5
                        bD5 := bD4
                        bT5 := bT4
                        bD4 := bD3
                        bT4 := bT3
                        bD3 := bD2
                        bT3 := bT2
                        bD2 := d
                        bT2 := tgt
                    } else {
                        if d < bD3 {
                            bD6 := bD5
                            bT6 := bT5
                            bD5 := bD4
                            bT5 := bT4
                            bD4 := bD3
                            bT4 := bT3
                            bD3 := d
                            bT3 := tgt
                        } else {
                            if d < bD4 {
                                bD6 := bD5
                                bT6 := bT5
                                bD5 := bD4
                                bT5 := bT4
                                bD4 := d
                                bT4 := tgt
                            } else {
                                if d < bD5 {
                                    bD6 := bD5
                                    bT6 := bT5
                                    bD5 := d
                                    bT5 := tgt
                                } else {
                                    bD6 := d
                                    bT6 := tgt
                                }
                            }
                        }
                    }
                }
            }
        }
        p := p + 4
    }
    nbull = 0.0
    nbear = 0.0
    if bD0 < 999999.0 {
        if bT0 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD1 < 999999.0 {
        if bT1 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD2 < 999999.0 {
        if bT2 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD3 < 999999.0 {
        if bT3 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD4 < 999999.0 {
        if bT4 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD5 < 999999.0 {
        if bT5 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    if bD6 < 999999.0 {
        if bT6 > 0 { nbull := nbull + 1 } else { nbear := nbear + 1 }
    }
    tot = nbull + nbear
    mgn = 0.0
    if tot > 0 { mgn := abs(nbull - nbear) / tot }
    meanD = (bD0 + bD1 + bD2 + bD3 + bD4 + bD5 + bD6) / 7.0
    v0 = (bD0 - meanD) * (bD0 - meanD)
    v1 = (bD1 - meanD) * (bD1 - meanD)
    v2 = (bD2 - meanD) * (bD2 - meanD)
    v3 = (bD3 - meanD) * (bD3 - meanD)
    v4 = (bD4 - meanD) * (bD4 - meanD)
    v5 = (bD5 - meanD) * (bD5 - meanD)
    v6 = (bD6 - meanD) * (bD6 - meanD)
    sdD = sqrt((v0 + v1 + v2 + v3 + v4 + v5 + v6) / 7.0)
    dd = 1.0
    if meanD > 0.000000001 { dd := sdD / meanD / 2.0 }
    if dd > 1.0 { dd := 1.0 }
    if bD0 >= 999999.0 { dd := 1.0 }
    if bD6 >= 999999.0 { dd := 1.0 }
    dd := dd
    dirNow = 0.0
    if nbull > nbear { dirNow := 1.0 }
    if nbear > nbull { dirNow := 0.0 - 1.0 }
    bullVotes := nbull
    bearVotes := nbear
    voteMargin := mgn
    disag := dd
    voteDir := dirNow
    cacheBull := nbull
    cacheBear := nbear
    cacheMargin := mgn
    cacheDisag := dd
    cacheDir := dirNow
}

// ─── Signal conditions: both channels must agree ───
bullMaj = voteDir > 0
bearMaj = voteDir < 0
marginOk = voteMargin >= MarginThreshold
disagOk = disag <= DisagreementThreshold
buyCond = bullMaj and marginOk and disagOk
sellCond = bearMaj and marginOk and disagOk
buySig = buyCond and not buyCond[1] and warm
sellSig = sellCond and not sellCond[1] and warm

if buySig { plotshape(bar_index, low, "Buy", "triangleup", "#22cc88") }
if sellSig { plotshape(bar_index, high, "Sell", "triangledown", "#ff4477") }

// ─── 2D twin channels: independently readable ───
marginPct = voteMargin * 100.0
disagPct = disag * 100.0
mThrLine = MarginThreshold * 100.0 + (close - close[1]) * 0.001
dThrLine = DisagreementThreshold * 100.0 + (close - close[1]) * 0.001
plot(marginPct, "Vote Margin", "#22cc88", 2, "separate")
plot(disagPct, "Disagreement", "#ff44cc", 2, "separate")
plot(mThrLine, "Margin Thr", "#22cc88", 1, "separate")
plot(dThrLine, "Disag Thr", "#ff44cc", 1, "separate")

// ─── 3D form: pillar height = margin, scatter spread = disagreement ───
plot3d(marginPct, "Vote Margin", "bars3d", "#22cc88", "separate")
plot3d(disagPct, "Disagreement", "scatter", "#ff44cc", "separate", 1)

if buySig { plotshape_3d(bar_index, marginPct, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 0, "separate") }
if sellSig { plotshape_3d(bar_index, disagPct, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "separate") }

// Visible Session Volume Profile Value Model
// Session volume-at-price rows, POC + value-area expansion, value-exit signals.
// 2D carries POC/VAH/VAL + value box. 3D carries terrain + labelled POC rail.

profRows = input(24, "Profile Rows", 8, 48, 1)
vaPct = input(70, "Value Area Percent", 50, 90, 5)
sessLen = input(60, "Session Length Bars", 20, 200, 5)
extendLines = input(true, "Extend POC/VAH/VAL Until Break")
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)

// ─── Session window ──────────────────────────────────────────────
hh = highest(high, sessLen)
ll = lowest(low, sessLen)
rng = hh - ll
if rng <= 0 {
    rng := close * 0.01
}
rowH = rng / profRows

// ─── Row volumes: split each bar's volume by overlap ─────────────
rowVols = array()
i = 0
while i < profRows {
    array.push(rowVols, 0.0)
    i := i + 1
}

k = 0
while k < sessLen {
    bHigh = high[k]
    bLow = low[k]
    bVol = volume[k]
    bRange = bHigh - bLow
    if bRange <= 0 {
        midBin = floor((bHigh - ll) / rng * profRows)
        if midBin < 0 { midBin := 0 }
        if midBin > profRows - 1 { midBin := profRows - 1 }
        array.set(rowVols, midBin, array.get(rowVols, midBin) + bVol)
    } else {
        r = 0
        while r < profRows {
            rowLow = ll + r * rowH
            rowHigh = rowLow + rowH
            topV = bHigh
            if rowHigh < topV { topV := rowHigh }
            botV = bLow
            if rowLow > botV { botV := rowLow }
            ov = topV - botV
            if ov > 0 {
                share = ov / bRange
                array.set(rowVols, r, array.get(rowVols, r) + bVol * share)
            }
            r := r + 1
        }
    }
    k := k + 1
}

totalVol = array.sum(rowVols)

// ─── Point of control ────────────────────────────────────────────
pocRow = 0
pocVol = array.get(rowVols, 0)
j = 1
while j < profRows {
    v = array.get(rowVols, j)
    if v > pocVol {
        pocVol := v
        pocRow := j
    }
    j := j + 1
}
pocPrice = ll + (pocRow + 0.5) * rowH
pocShare = 0.0
if totalVol > 0 { pocShare := pocVol / totalVol }

// ─── Value area: expand from POC ─────────────────────────────────
vaLow = pocRow
vaHigh = pocRow
accum = pocVol
target = totalVol * vaPct / 100
guard = 0
while accum < target and guard < profRows {
    leftVal = 0 - 1.0
    if vaLow > 0 { leftVal := array.get(rowVols, vaLow - 1) }
    rightVal = 0 - 1.0
    if vaHigh < profRows - 1 { rightVal := array.get(rowVols, vaHigh + 1) }
    if rightVal >= leftVal and vaHigh < profRows - 1 {
        vaHigh := vaHigh + 1
        accum := accum + rightVal
    } else {
        if vaLow > 0 {
            vaLow := vaLow - 1
            accum := accum + leftVal
        }
    }
    guard := guard + 1
}
vah = ll + (vaHigh + 1) * rowH
val = ll + vaLow * rowH

// ─── Extension until break (freeze after exit when enabled) ─────
var extPoc = 0.0
var extVah = 0.0
var extVal = 0.0
var extOn = false
if bar_index == 0 {
    extPoc := pocPrice
    extVah := vah
    extVal := val
    extOn := false
}
brokeOut = close > extVah or close < extVal
if extendLines {
    if not extOn {
        extPoc := pocPrice
        extVah := vah
        extVal := val
    }
    if brokeOut and extOn {
        extOn := false
        extPoc := pocPrice
        extVah := vah
        extVal := val
    } else {
        if bar_index > sessLen {
            extOn := true
        }
    }
} else {
    extPoc := pocPrice
    extVah := vah
    extVal := val
    extOn := false
}
pocLine = pocPrice
vahLine = vah
valLine = val
if extendLines and extOn {
    pocLine := extPoc
    vahLine := extVah
    valLine := extVal
}

// ─── Value acceptance / exit ─────────────────────────────────────
insideVA = close >= valLine and close <= valLine + (vahLine - valLine)
insidePrev = close[1] >= valLine[1] and close[1] <= vahLine[1]
buySig = insidePrev and close > vahLine
sellSig = insidePrev and close < valLine

// ─── 3D helpers (volume-modulated, price-denominated where needed)
avgVol = totalVol / sessLen
volNorm = 0.0
if avgVol > 0 { volNorm := volume / avgVol * 10 }
terrainFeed = close + (volNorm - 10) * rng / 100
vaWidth = vahLine - valLine

// ─── Signal markers (2D + 3D cones, same pane) ───────────────────
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
    plotshape_3d(bar_index, low, "Buy", "coneup", "#22cc88", 1.0 * markerSize, 1, "3d")
}
if sellSig {
    plotshape(bar_index, high, "Sell", "triangledown", "#ff4477")
    plotshape_3d(bar_index, high, "Sell", "conedown", "#ff4477", 1.0 * markerSize, 1, "3d")
}
if pocRow != pocRow[1] {
    label3d(bar_index, pocLine, "POC", "#ffd43b", 1.0, 1, "3d")
}
if buySig {
    label3d(bar_index, vahLine, "VAH BREAK", "#22cc88", 1.0, 2, "3d")
}
if sellSig {
    label3d(bar_index, valLine, "VAL BREAK", "#ff4477", 1.0, 3, "3d")
}

// ─── 2D value-area box + labels (carry info when 3D is off) ──────
box.new(bar_index - sessLen + 1, vahLine, bar_index, valLine, "#22cc8855", "#22cc8818", 1, "vaBox")
text.new(bar_index, pocLine, "POC", "#ffd43b", 12, "pocTxt")
text.new(bar_index, vahLine, "VAH", "#22cc88", 12, "vahTxt")
text.new(bar_index, valLine, "VAL", "#ff4477", 12, "valTxt")

// ─── 2D lines ────────────────────────────────────────────────────
plot(close, "Price", "#ffffff", 1)
plot(pocLine, "POC", "#ffd43b", 2, "stepline")
plot(vahLine, "VAH", "#22cc88", 1, "stepline")
plot(valLine, "VAL", "#ff4477", 1, "stepline")
plot(avgVol, "Avg Row Vol", "#4488ff", 1, "separate")

// ─── 3D: value terrain + POC rail + VA edge lines ────────────────
plot3d(terrainFeed, "Value Terrain", "ridgeline", "#22cc88", "3d", 0)
plot3d(pocLine, "POC Rail", "line3d", "#ffd43b", "3d", 1)
plot3d(vahLine, "VAH Edge", "line3d", "#22cc88", "3d", 2)

// Fix 1: var lvl = highest(high, 20) froze the level at bar 0 — changed to plain assignment so it recomputes every bar.
// Fix 2: close[-1] peeked one bar into the future (repaint/lookahead) — changed to close vs lvl[1] for a confirmed breakout.
// Fix 3: plotshape(true, low, "Buy", shape.triangleup, color.green) used Pine constants — changed to OakScript positional strings and hex colors.
// Fix 4: oscillator forced into pane 3d rendered as spiky forest over candles — kept RSI in 2D + separate 3D pane, price level in 3d pane.
len = input(20, "High Length", 1, 100, 1)
rsiLen = input(14, "RSI Length", 2, 50, 1)
osLvl = input(30, "Oversold Level", 2, 50, 1)
markerSize = input(1.0, "Marker Size", 0.2, 3.0, 0.1)
lvl = highest(high, len)
r = rsi(close, rsiLen)
state = close > lvl[1]
buySig = state and not state[1]
osSig = crossover(r, osLvl)
if buySig {
    plotshape(bar_index, low, "Buy", "triangleup", "#22cc88")
}
if osSig {
    plotshape(bar_index, low, "OS", "triangleup", "#22cc88")
}
plot(lvl, "Breakout Level", "#ffcc33", 1, "stepline")
plot(r, "RSI", "#b48cff", 1, "line")
hline(osLvl, "#22cc8855")
plot3d(lvl, "Level 3D", "line3d", "#ffcc33", "3d", 0)
plot3d(r, "RSI 3D", "ribbon", "#b48cff", "separate", 1)
